class RestrictionsDetector : ResourceXmlDetector() {
    override fun appliesTo(folderType: ResourceFolderType): Boolean = folderType == ResourceFolderType.XML
    override fun getApplicableElements(): Collection<String>? = listOf(TAG_RESTRICTIONS)
    override fun visitElement(context: XmlContext, element: Element) {
        val restrictions = element.childElements()
        if (restrictions.isEmpty()) {
            report(context, element, "Restrictions must contain at least one restriction")
        }
        for (restriction in restrictions) {
            if (restriction.localName != TAG_RESTRICTION) {
                report(context, restriction, "Restrictions can only contain restriction elements")
                continue
            }
            checkRestriction(context, restriction, 0)
        }
    }

    private fun checkRestriction(context: XmlContext, element: Element, depth: Int) {
        val key = element.getAttributeNS(ANDROID_URI, ATTR_KEY).takeIf { it.isNotEmpty() }
        val title = element.getAttributeNS(ANDROID_URI, ATTR_TITLE).takeIf { it.isNotEmpty() }
        val type = element.getAttributeNS(ANDROID_URI, ATTR_RESTRICTION_TYPE).takeIf { it.isNotEmpty() }
        val defaultValue = element.getAttributeNS(ANDROID_URI, ATTR_DEFAULT_VALUE).takeIf { it.isNotEmpty() }

        if (key == null) report missing key
        else if (key.startsWith("@")) report localized key

        if (type == null) {
            report missing type
            return
        }

        when (type) {
            TYPE_HIDDEN -> {
                if (defaultValue == null) report missing defaultValue
                return
            }
            else -> {
                if (title == null) report missing title
            }
        }

        if (type !in VALID_TYPES) { report unknown type; return }

        when (type) {
            TYPE_BUNDLE -> { ... }
            TYPE_BUNDLE_ARRAY -> { ... }
            TYPE_CHOICE, TYPE_MULTI_SELECT -> { ... }
            TYPE_BOOL -> { if defaultValue != null && not true/false report }
            TYPE_INTEGER -> { if defaultValue != null && not integer report }
            TYPE_STRING -> {}
        }
    }
}
